package com.devopsclassroom.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="trabalhos") public class Trabalho { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=180) private String titulo; @Column(length=2000) private String descricao; @Column(name="pontuacao_maxima",nullable=false) private Integer pontuacaoMaxima=100; @Column(name="prazo_entrega") private LocalDateTime prazoEntrega; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="turma_id",nullable=false) @JsonIgnore private Turma turma; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="professor_id",nullable=false) @JsonIgnore private Usuario professor; @Column(name="trabalho_equipe",nullable=false) private boolean trabalhoEquipe=false; @Lob @Column(name="checklist_json",nullable=false) private String checklistJson="[]"; public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitulo(){return titulo;} public void setTitulo(String v){titulo=v;} public String getDescricao(){return descricao;} public void setDescricao(String v){descricao=v;} public Integer getPontuacaoMaxima(){return pontuacaoMaxima;} public void setPontuacaoMaxima(Integer v){pontuacaoMaxima=v;} public LocalDateTime getPrazoEntrega(){return prazoEntrega;} public void setPrazoEntrega(LocalDateTime v){prazoEntrega=v;} public Turma getTurma(){return turma;} public void setTurma(Turma v){turma=v;} public Usuario getProfessor(){return professor;} public void setProfessor(Usuario v){professor=v;} public boolean isTrabalhoEquipe(){return trabalhoEquipe;} public void setTrabalhoEquipe(boolean v){trabalhoEquipe=v;} public String getChecklistJson(){return checklistJson;} public void setChecklistJson(String v){checklistJson=v;} }
